"""Source-specific author extraction. Independent scientific review remains pending."""
import collections
import datetime as dt
import hashlib
import json
from pathlib import Path
from pypdf import PdfReader

B=Path(__file__).resolve().parent
SID='gu2004'
now=dt.datetime.now(dt.timezone.utc).isoformat()
docs={d['role_candidate']:d for d in json.loads((B/'intake-manifest.json').read_bytes())['documents']}
for role,d in docs.items():
 p=Path(d['path'])
 assert hashlib.sha256(p.read_bytes()).hexdigest()==d['sha256']
 assert len(PdfReader(p).pages)==d['page_count']
units=[];facts=[];operations=[];materials=[];samples=[];references=[]

def unit(key,role,page,locator,kind,claim,scope='study',disposition='retain_source_evidence',assets=(),refs=()):
 item={'id':SID+'-'+key,'source_unit_id':SID+'-'+key,'source_role':role,'pdf_page':page,'printed_page':str(5663+page) if role=='main' else 'S'+str(page),'locator':locator,'kind':kind,'claim':claim,'sample_scope':scope,'disposition':disposition,'original_asset_ids':[SID+'-'+a for a in assets],'reference_ids':list(refs),'independent_review_status':'pending'}
 units.append(item);return item['id']

def fact(uid,key,value,unit_name=None,status='reported',scope=None,approximate=False,minimum=None,maximum=None,qualifier='',raw_text=None):
 u=next(x for x in units if x['id']==uid)
 item={'id':SID+'-fact-'+key,'source_unit_id':uid,'sample_scope':scope or u['sample_scope'],'property':key,'raw_text':raw_text,'value':value,'minimum':minimum,'maximum':maximum,'minimum_exclusive':False,'maximum_exclusive':False,'unit':unit_name,'approximate':approximate,'status':status,'qualifier':qualifier,'evidence':[{'source_role':u['source_role'],'pdf_page':u['pdf_page'],'locator':u['locator'],'source_sha256':docs[u['source_role']]['sha256']}],'eligible_training':False,'independent_review_status':'pending'}
 facts.append(item);return item['id']

def op(key,protocol,action,claim,inputs,output,loc,quantities=(),retained=None,missing=()):
 uid=unit(key,'si',1,loc,'operation',claim,scope=protocol,assets=('si-cdacac-preparation' if protocol=='cdacac-preparation' else 'si-heterodimer-preparation',))
 qids=[]
 for q in quantities:
  name,val,un,*extra=q
  opts=extra[0] if extra else {}
  qids.append(fact(uid,key+'-'+name,val,un,**opts))
 operations.append({'id':SID+'-'+key,'protocol_id':SID+'-'+protocol,'source_unit_id':uid,'action':action,'description':claim,'inputs':inputs,'output':output,'retained_fraction':retained,'quantity_fact_ids':qids,'unreported_fields':list(missing),'atmosphere_scope':'SI General says all reactions inert unless stated; gas identity/pressure unknown except final nitrogen storage; vacuum stated for upstream drying.'})
 return uid

