unit('fept-saed-claim','main',1,'Figure 1A discussion; ref 7','structural_assignment','Authors state that SAED of 1 indicates disordered face-centered cubic FePt and cite SI. The supplied SI contains no separately identifiable SAED image of 1; Figure 1D is explicitly product 4.',scope='FePt 1',disposition='retain_reported_assignment_and_missing_original_image',refs=['main-7'])
u=unit('final-tem-dimensions','main',1,'Figure 1B/C discussion','measurement','Final 4 is described as almost monodisperse; FePt component diameters remain 2.5 nm and CdS components are approximately 3–4 nm. No statistical particle count or distribution width is reported.',scope='final product 4',assets=('figure-1',));fact(u,'final-fept-component-diameter',2.5,'nm');fact(u,'final-cds-component-diameter',None,'nm',minimum=3,maximum=4,approximate=True)
