u=unit('final-saed-phases','main',1,'Figure 1D discussion','structural_assignment','Final-product SAED rings assigned to zinc-blende CdS {111},{220},{311} and disordered FCC FePt {111},{200},{220},{311}. These are phase/index assignments, not a refined atomic structure or measured unit-cell parameter.',scope='final product 4',assets=('figure-1',));fact(u,'final-cds-phase','zinc blende');fact(u,'final-fept-phase','disordered face-centered cubic');fact(u,'cds-saed-reflections',['111','220','311']);fact(u,'fept-saed-reflections',['111','200','220','311'])
u=unit('final-xrf-ratio','main',1,'XRF composition paragraph','measurement','Main reports Fe/Pt/Cd/S ≈ 1:1:3:3.6 and FePt/CdS ≈ 1:3, saying this agrees with the component volume ratio in TEM. This is the authors’ reported relation; no XRF correction method or conversion derivation is provided.',scope='final product 4',assets=('figure-s1',));fact(u,'reported-fe-pt-cd-s-ratio',[1,1,3,3.6],'ratio',approximate=True);fact(u,'reported-fept-cds-ratio',[1,3],'ratio',approximate=True)
