unit('property-conservation-rationale','main',1,'Before magnetic measurements','author_interpretation','Authors infer preservation of individual-component functions from composition/structure conservation and test magnetic/optical properties. This is a component-function argument, not proof of all properties remaining unchanged.',scope='FePt 1 versus final 4')
unit('magnetic-timing','main',1,'Magnetic measurements paragraph','acquisition','Magnetic measurements of 4 were performed immediately after synthesis. Exact elapsed time, specimen preparation/state/mass, instrument and field protocol are not otherwise detailed.',scope='final product 4 magnetic sample')
u=unit('magnetic-zfc-fc','main',1,'Magnetic measurements paragraph; Figure 2A caption on main p2','measurement','ZFC/FC of 4 gives an estimated blocking temperature around 11 K. Figure 2A specifies applied field 100 Oe. Sharp peak and an origin-crossing extrapolated 1/m versus T plot are interpreted as uniform FePt sizes and weak dipolar interaction.',scope='final product 4 magnetic sample',assets=('figure-2',));fact(u,'blocking-temperature',11,'K',approximate=True);fact(u,'zfc-fc-applied-field',100,'Oe',qualifier='Acquisition field appears in main p2 Figure 2A caption; this value is not inherited by SI S-3.')
unit('magnetic-weak-interactions','main',1,'End of magnetic paragraph; continuation main p2','author_interpretation','Sharp ZFC peak and extrapolated FC inverse moment through the origin are the authors’ evidence for a narrow FePt size distribution and weak interparticle magnetic dipolar interaction; no numerical interaction strength is reported.',scope='final product 4 magnetic sample',disposition='retain_author_interpretation',assets=('figure-2',))
u=unit('magnetic-equation','main',2,'First left-column paragraph','author_model','Printed relation t_mes = τ_0 exp(K_u V/(k_B T_B)); t_mes = 30 s, τ_0 ≈ 10^−10 s, using TEM FePt diameter ≈2.5 nm and blocking temperature to estimate K_u ≈2.4×10^6 erg/cm³. τ_0 is a model input; K_u is author-derived, not independently measured. No separate raw fitting output or uncertainty is supplied.',scope='anisotropy estimate for FePt component in 4',disposition='retain_author_model_not_experimental_structure',assets=('magnetic-model',));fact(u,'magnetic-observation-time',30,'s',status='author_model_input');fact(u,'magnetic-attempt-time',1e-10,'s',status='author_model_input',approximate=True);fact(u,'magnetic-anisotropy',2.4e6,'erg/cm^3',status='author_derived',approximate=True);fact(u,'model-fept-diameter',2.5,'nm',status='author_model_input',approximate=True)
