u=unit('hysteresis','main',2,'Field-dependent magnetization paragraph and Fig 2B caption','measurement','Product 4 measured at 5 K has hysteresis and coercivity around 0.85 kOe. Source concludes magnetic function is retained; this does not mean the sample is non-hysteretic at all temperatures.',scope='final product 4 magnetic sample',assets=('figure-2',));fact(u,'hysteresis-temperature',5,'K');fact(u,'coercivity',.85,'kOe',approximate=True)
u=unit('optical-fept-band','main',2,'UV–visible discussion','measurement_and_assignment','Absorption at 293 nm in product 4 is assigned to FePt and described as agreeing with precursor 1 and prior observations. Keep 293 nm scoped to 4; the SI precursor trace is not supplied as tabulated peak data.',scope='product 4 in hexane',assets=('figure-2','figure-s2'),refs=['main-9a','main-9b','main-9c']);fact(u,'fept-assigned-absorption',293,'nm')
u=unit('optical-cds-shoulder','main',2,'UV–visible discussion','measurement_and_assignment','Absorption shoulder centered at 369 nm in 4 is compared with literature CdS quantum dots. It is an absorption shoulder, not the emission peak or a crystal-size calibration.',scope='product 4 in hexane',assets=('figure-2',),refs=['main-1']);fact(u,'cds-assigned-absorption-shoulder',369,'nm')
